div.script:
                    // Global variables
                    let cart = [];
                    let selectedSlot = null;

                    // Initialize on page load
                    document.addEventListener('DOMContentLoaded', function() {
                        setDefaultDate();
                        generateCalendar();
                        loadCart();
                    });

                    function setDefaultDate() {
                        const today = new Date().toISOString().split('T')[0];
                        document.getElementById('appointmentDate').value = today;
                        document.getElementById('appointmentDate').min = today;
                    }

                    function generateCalendar() {
                        const tbody = document.getElementById('calendarBody');
                        tbody.innerHTML = '';

                        // Generate 30-minute time slots from 8:00 AM to 5:30 PM
                        const timeSlots = [];
                        for (let hour = 8; hour <= 17; hour++) {
                            for (let minute = 0; minute < 60; minute += 30) {
                                const timeStr = hour.toString().padStart(2, '0') + ':' + minute.toString().padStart(2, '0');
                                const displayTime = formatTime(hour, minute);
                                timeSlots.push({ time: timeStr, display: displayTime });
                            }
                        }

                        const employees = [
                            { id: 1, name: 'Sarah Johnson', price: 50 },
                            { id: 2, name: 'Mike Davis', price: 45 },
                            { id: 3, name: 'Lisa Wilson', price: 55 }
                        ];

                        // Generate table rows
                        timeSlots.forEach(function(slot) {
                            const row = document.createElement('tr');

                            // Time cell
                            const timeCell = document.createElement('td');
                            timeCell.className = 'time-cell';
                            timeCell.innerHTML = ' ' + slot.display;
                            row.appendChild(timeCell);

                            // Employee cells
                            employees.forEach(function(emp) {
                                const cell = document.createElement('td');
                                cell.className = 'text-center';

                                const isAvailable = Math.random() > 0.3;

                                if (isAvailable) {
                                    const button = document.createElement('button');
                                    button.className = 'slot-btn slot-available';
                                    button.textContent = slot.display;
                                    button.onclick = function() {
                                        selectSlot(slot.time, slot.display, emp);
                                    };
                                    cell.appendChild(button);
                                } else {
                                    const button = document.createElement('button');
                                    button.className = 'slot-btn slot-empty';
                                    button.textContent = '-';
                                    button.disabled = true;
                                    cell.appendChild(button);
                                }

                                row.appendChild(cell);
                            });

                            tbody.appendChild(row);
                        });
                    }

                    function formatTime(hour, minute) {
                        const period = hour >= 12 ? 'PM' : 'AM';
                        const displayHour = hour > 12 ? hour - 12 : (hour === 0 ? 12 : hour);
                        const displayMinute = minute.toString().padStart(2, '0');
                        return displayHour + ':' + displayMinute + ' ' + period;
                    }

                    function selectSlot(time, displayTime, employee) {
                        // Clear previous selections
                        document.querySelectorAll('.slot-btn').forEach(function(btn) {
                            btn.classList.remove('slot-selected');
                        });

                        // Mark current selection
                        event.target.classList.add('slot-selected');

                        // Store selection
                        selectedSlot = {
                            time: time,
                            displayTime: displayTime,
                            employee: employee,
                            date: document.getElementById('appointmentDate').value,
                            service: 'Hair Cut Service'
                        };

                        // Show selection details
                        showSelection();
                    }

                    function showSelection() {
                        const selectionDiv = document.getElementById('currentSelection');
                        const infoDiv = document.getElementById('selectedSlotInfo');

                        infoDiv.innerHTML = 
                            ' ' + selectedSlot.displayTime + '
' +
                            '' + formatDate(selectedSlot.date) + '
' +
                            ' ' + selectedSlot.employee.name + '
' +
                            ' ' + selectedSlot.service + '
' +
                            '$' + selectedSlot.employee.price + '.00';

                        selectionDiv.style.display = 'block';
                    }

                    async function addToCart() {
                        if (!selectedSlot) return;

                        try {
                            const response = await fetch('/appointment/cart/add', {
                                method: 'POST',
                                headers: { 'Content-Type': 'application/json' },
                                body: JSON.stringify({
                                    jsonrpc: '2.0',
                                    method: 'call',
                                    params: {
                                        appointment_data: {
                                            employee_name: selectedSlot.employee.name,
                                            employee_id: selectedSlot.employee.id,
                                            date: selectedSlot.date,
                                            time: selectedSlot.time,
                                            display_time: selectedSlot.displayTime,
                                            service: selectedSlot.service,
                                            price: selectedSlot.employee.price
                                        }
                                    }
                                })
                            });

                            const result = await response.json();

                            if (result.result && result.result.success) {
                                // Add to local cart
                                const cartItem = { id: Date.now(), ...selectedSlot };
                                cart.push(cartItem);

                                // Mark slot as booked
                                const targetButton = document.querySelector('.slot-selected');
                                if (targetButton) {
                                    targetButton.classList.remove('slot-available', 'slot-selected');
                                    targetButton.classList.add('slot-booked');
                                    targetButton.textContent = 'Booked';
                                    targetButton.disabled = true;
                                }

                                updateCart();
                                cancelSelection();
                                showNotification('Appointment added to cart!', 'success');
                            } else {
                                throw new Error(result.result ? result.result.error : 'Failed to add to cart');
                            }
                        } catch (error) {
                            console.error('Cart error:', error);
                            showNotification('Failed to add to cart: ' + error.message, 'danger');
                        }
                    }

                    function updateCart() {
                        const cartItemsDiv = document.getElementById('cartItems');
                        const cartCount = document.getElementById('cartCount');
                        const cartTotal = document.getElementById('cartTotal');
                        const totalAmount = document.getElementById('totalAmount');

                        cartCount.textContent = cart.length;

                        if (cart.length === 0) {
                            cartItemsDiv.innerHTML = 
                                '
' +
                                '' +
                                '
Your cart is empty' +
                                '';
                            cartTotal.style.display = 'none';
                        } else {
                            let total = 0;
                            let itemsHtml = '';

                            cart.forEach(function(item) {
                                total += item.employee.price;
                                itemsHtml += 
                                    '
' +
                                    '
' +
                                    '' + item.displayTime + '
' +
                                    '' + item.employee.name + ' - ' + item.service + '
' +
                                    '' + formatDate(item.date) + '' +
                                    '' +
                                    '
' +
                                    '$' + item.employee.price + '
' +
                                    '' +
                                    '' +
                                    '' +
                                    '' +
                                    '';
                            });

                            cartItemsDiv.innerHTML = itemsHtml;
                            totalAmount.textContent = total.toFixed(2);
                            cartTotal.style.display = 'block';
                        }
                    }

                    function removeFromCart(itemId) {
                        cart = cart.filter(function(item) { return item.id !== itemId; });
                        updateCart();
                        showNotification('Item removed from cart', 'info');
                    }

                    function cancelSelection() {
                        selectedSlot = null;
                        document.getElementById('currentSelection').style.display = 'none';
                        document.querySelectorAll('.slot-btn').forEach(function(btn) {
                            btn.classList.remove('slot-selected');
                        });
                    }

                    function proceedToCheckout() {
                        if (cart.length === 0) {
                            showNotification('Your cart is empty!', 'warning');
                            return;
                        }
                        window.location.href = '/shop/checkout';
                    }

                    function loadCalendarForDate() {
                        generateCalendar();
                        cancelSelection();
                    }

                    function loadCart() {
                        const savedCart = sessionStorage.getItem('appointmentCart');
                        if (savedCart) {
                            cart = JSON.parse(savedCart);
                            updateCart();
                        }
                    }

                    function formatDate(dateStr) {
                        const date = new Date(dateStr);
                        return date.toLocaleDateString('en-US', { 
                            weekday: 'long', 
                            year: 'numeric', 
                            month: 'long', 
                            day: 'numeric' 
                        });
                    }

                    function showNotification(message, type) {
                        const notification = document.createElement('div');
                        notification.className = 'alert alert-' + type + ' alert-dismissible fade show';
                        notification.style.position = 'fixed';
                        notification.style.top = '20px';
                        notification.style.right = '20px';
                        notification.style.zIndex = '9999';
                        notification.innerHTML = 
                            message +
                            '' +
                            'X' +
                            '';
                        document.body.appendChild(notification);

                        setTimeout(function() {
                            if (notification.parentElement) {
                                notification.remove();
                            }
                        }, 3000);
                    }

                    // Save cart to session storage
                    window.addEventListener('beforeunload', function() {
                        sessionStorage.setItem('appointmentCart', JSON.stringify(cart));
                    });

template.script:
                    console.log('🟢 CALENDAR DEBUG: Calendar page script executing');
                    console.log('🟢 CALENDAR DEBUG: Current URL:', window.location.href);

                    // Setup default session data if missing (for testing purposes)
                    function setupDefaultSessionData() {
                        if (!sessionStorage.getItem('selectedService')) {
                            const defaultService = {
                                id: 9, // Our test product ID
                                name: 'Hair Cut Service',
                                category_id: 5
                            };
                            sessionStorage.setItem('selectedService', JSON.stringify(defaultService));
                            console.log('🔧 Set default service:', defaultService);
                        }

                        if (!sessionStorage.getItem('selectedBranch')) {
                            const defaultBranch = {
                                id: 1,
                                name: 'Main Branch'
                            };
                            sessionStorage.setItem('selectedBranch', JSON.stringify(defaultBranch));
                            console.log('🔧 Set default branch:', defaultBranch);
                        }

                        if (!sessionStorage.getItem('locationType')) {
                            sessionStorage.setItem('locationType', 'inside');
                            console.log('🔧 Set default location type: inside');
                        }
                    }

                    // Wait for DOM to be fully loaded
                    document.addEventListener('DOMContentLoaded', function() {
                        console.log('🟢 CALENDAR DEBUG: DOM loaded, checking elements');
                        console.log('🟢 CALENDAR DEBUG: Calendar elements exist:', {
                            calHead: !!document.getElementById('calHead'),
                            calBody: !!document.getElementById('calBody'),
                            dateNavigation: !!document.getElementById('dateNavigation'),
                            calendarContainer: !!document.getElementById('calendarContainer'),
                            bookingSummary: !!document.getElementById('bookingSummary')
                        });

                        // Setup session data for testing
                        setupDefaultSessionData();

                        // Initialize calendar after a short delay to ensure all scripts are loaded
                        setTimeout(function() {
                            console.log('🟢 CALENDAR DEBUG: Attempting calendar initialization...');

                            // Check if we have session data for the booking
                            const selectedService = JSON.parse(sessionStorage.getItem('selectedService') || '{}');
                            const selectedBranch = JSON.parse(sessionStorage.getItem('selectedBranch') || '{}');
                            const locationType = sessionStorage.getItem('locationType');

                            console.log('🟢 CALENDAR DEBUG: Session data:', {
                                selectedService,
                                selectedBranch,
                                locationType
                            });

                            if (typeof window.initializeCalendar === 'function') {
                                console.log('🟢 CALENDAR DEBUG: initializeCalendar function found, calling...');
                                window.initializeCalendar();
                            } else if (typeof window.forceInitializeCalendar === 'function') {
                                console.log('🟢 CALENDAR DEBUG: Using forceInitializeCalendar...');
                                window.forceInitializeCalendar();
                            } else {
                                console.log('🔴 CALENDAR DEBUG: No calendar initialization function found');
                                console.log('🔴 CALENDAR DEBUG: Available window functions:', 
                                    Object.keys(window).filter(key => key.toLowerCase().includes('calendar')));

                                // Force calendar display with test data
                                window.forceDisplayCalendar = function() {
                                    console.log('🎨 Forcing calendar display with test data...');

                                    const calHead = document.getElementById('calHead');
                                    const calBody = document.getElementById('calBody');

                                    if (!calHead || !calBody) {
                                        console.log('❌ Calendar elements not found');
                                        return;
                                    }

                                    // Create test employees
                                    const testEmployees = {
                                        1: { name: 'Sarah Johnson', branch_name: 'Main Branch', price_inside: 50.00, duration: 60 },
                                        2: { name: 'Mike Davis', branch_name: 'Downtown', price_inside: 55.00, duration: 60 },
                                        3: { name: 'Emma Wilson', branch_name: 'Mall Location', price_inside: 60.00, duration: 60 }
                                    };

                                    // Create header
                                    let headerHtml = '
⏰ TIME';
                                    Object.entries(testEmployees).forEach(([empId, emp]) => {
                                        headerHtml += '
' +
                                            '
' + emp.name.charAt(0) + '' +
                                            '
' +
                                                '
' + emp.name + '' +
                                                '
' + emp.branch_name + '' +
                                                '
$' + emp.price_inside + '' +
                                                '
' + emp.duration + ' min' +
                                            '' +
                                        '';
                                    });
                                    calHead.innerHTML = headerHtml;

                                    // Create body with time slots (30-minute intervals)
                                    let timeColumnHtml = '';
                                    for (let hour = 8; hour <= 18; hour++) {
                                        for (let minutes = 0; minutes < 60; minutes += 30) {
                                            const displayHour = hour > 12 ? hour - 12 : hour;
                                            const ampm = hour >= 12 ? 'PM' : 'AM';
                                            const minuteStr = minutes === 0 ? '00' : minutes.toString();
                                            timeColumnHtml += '
' + displayHour + ':' + minuteStr + ' ' + ampm + '';
                                        }
                                    }

                                    let bodyHtml = '
' + timeColumnHtml + '';
                                    Object.keys(testEmployees).forEach(empId => {
                                        let empColumnHtml = '';
                                        for (let hour = 8; hour <= 18; hour++) {
                                            for (let minutes = 0; minutes < 60; minutes += 30) {
                                                const timeStr = hour + ':' + (minutes === 0 ? '00' : minutes.toString());
                                                if (hour >= 9 && hour <= 17 && Math.random() > 0.3) {
                                                    // Add available slot button
                                                    empColumnHtml += '
' +
                                                        '' +
                                                            timeStr +
                                                        '' +
                                                    '';
                                                } else {
                                                    empColumnHtml += '
' +
                                                        '
' +
                                                    '';
                                                }
                                            }
                                        }
                                        bodyHtml += '
' + empColumnHtml + '';
                                    });

                                    calBody.innerHTML = bodyHtml;

                                    // Update grid columns
                                    const empCount = Object.keys(testEmployees).length;
                                    calHead.style.gridTemplateColumns = '100px repeat(' + empCount + ', 1fr)';
                                    calBody.style.gridTemplateColumns = '100px repeat(' + empCount + ', 1fr)';
                                    calBody.style.setProperty('--cols', empCount);

                                    console.log('✅ Test calendar displayed successfully!');
                                };

                                // Test slot selection
                                window.testSlotSelect = function(time, empId) {
                                    console.log('🎯 Selected slot: ' + time + ' for employee ' + empId);

                                    // Show booking summary
                                    const summaryDiv = document.getElementById('bookingSummary');
                                    const slotInfo = document.getElementById('selectedSlotInfo');

                                    if (summaryDiv && slotInfo) {
                                        slotInfo.innerHTML = 
                                            '
Time: ' + time + '' +
                                            '
Employee: Employee ' + empId + '' +
                                            '
Service: Hair Cut Service' +
                                            '
Price: $50.00';

                                        summaryDiv.style.display = 'block';

                                        // Store slot data for booking
                                        window.selectedSlotData = {
                                            time: time,
                                            employee_id: empId,
                                            service_id: 9,
                                            price: 50.00
                                        };
                                    }
                                };

                                // Auto-display test calendar
                                setTimeout(window.forceDisplayCalendar, 2000);
                            }
                        }, 1500);
                    });

                    // Enhanced slot booking functions
                    window.confirmSlotBooking = function() {
                        console.log('🎯 Confirming slot booking...');

                        if (!window.selectedSlotData) {
                            alert('Please select a time slot first.');
                            return;
                        }

                        const slotData = window.selectedSlotData;

                        // Prepare booking data
                        const bookingData = {
                            service_id: slotData.service_id || 9,
                            employee_id: slotData.employee_id || 1,
                            slot_ids: [323, 324], // Test slot IDs
                            date: new Date().toISOString().split('T')[0],
                            appointment_type: 'inside',
                            price: slotData.price || 50.00
                        };

                        console.log('Booking data:', bookingData);

                        // Make booking request
                        fetch('/book-appointment/api/cart/add', {
                            method: 'POST',
                            headers: {
                                'Content-Type': 'application/json',
                            },
                            body: JSON.stringify(bookingData)
                        })
                        .then(response => response.json())
                        .then(data => {
                            console.log('Booking response:', data);
                            if (data.success) {
                                alert('Appointment booked successfully! Time: ' + slotData.time);
                                // Hide booking summary
                                document.getElementById('bookingSummary').style.display = 'none';
                                window.selectedSlotData = null;
                            } else {
                                alert('Booking failed: ' + (data.error || 'Please try again.'));
                            }
                        })
                        .catch(error => {
                            console.error('Booking error:', error);
                            alert('Booking failed due to a network error. Please try again.');
                        });
                    };

                    window.cancelSlotSelection = function() {
                        console.log('❌ Cancelling slot selection...');
                        const summaryDiv = document.getElementById('bookingSummary');
                        if (summaryDiv) {
                            summaryDiv.style.transition = 'all 0.3s ease-out';
                            summaryDiv.style.opacity = '0';
                            summaryDiv.style.transform = 'translateY(-20px)';
                            setTimeout(() => {
                                summaryDiv.style.display = 'none';
                            }, 300);
                        }

                        // Clear selected slot data
                        window.selectedSlotData = null;
                    };
